package handlers
// CancelOrder handles seller cancellation.
func CancelOrder(order Order, bus Bus) error {
    return bus.Publish("OrderCancelled", OrderCancelled{OrderID: order.ID, BuyerID: order.BuyerID, Reason: "seller_cancelled"})
}

{
  "event": "OrderCancelled",
  "producer": "order-service",
  "consumer": "notification-service",
  "fields": {
    "order_id": "string",
    "buyer_id": "string",
    "reason": "string"
  },
  "delivery": "at-least-once"
}

package consumers
// Subscribed to OrderCancelled.
func OnOrderCancelled(event OrderCancelled, mail Mailer) error {
    if event.Reason != "payment_expired" { return nil }
    return mail.Send(event.BuyerID, "order_cancelled", event.OrderID)
}

{
  "order-service": {
    "team": "orders",
    "events": [
      "OrderCancelled"
    ]
  },
  "notification-service": {
    "team": "messaging",
    "consumes": [
      "OrderCancelled"
    ]
  }
}

package mailer

// Synthetic fragment. Email is the only implemented channel.
type Mailer interface {
    Send(buyerID string, template string, orderID string) error
}
// Registered template: order_cancelled. Push and SMS are not implemented.
// Send has no idempotency guarantee; the caller must handle duplicate events.

package handlers

// Synthetic fragment: подтверждение доставки отправления.
func MarkDelivered(shipment Shipment, bus Bus) error {
    return bus.Publish("ShipmentDelivered", ShipmentDelivered{
        ShipmentID: shipment.ID,
        OrderID: shipment.OrderID,
        DeliveredAt: shipment.DeliveredAt,
    })
}

package consumers

// Synthetic fragment. Subscription: ShipmentDelivered.
func OnShipmentDelivered(event ShipmentDelivered, orders Store) error {
    // Current defect: records time but leaves status as shipped.
    return orders.SetDeliveredAt(event.OrderID, event.DeliveredAt)
}

{
  "event": "ShipmentDelivered",
  "producer": "delivery-service",
  "consumer": "order-service",
  "fields": {
    "shipment_id": "string",
    "order_id": "string",
    "delivered_at": "RFC3339 timestamp"
  },
  "delivery": "at-least-once"
}

package handlers

// Synthetic fragment: изменение остатка товара, не отмена заказа.
func AdjustStock(product Product, bus Bus) error {
    return bus.Publish("StockAdjusted", StockAdjusted{ProductID: product.ID, Count: product.Count})
}

{
  "event": "StockAdjusted",
  "producer": "inventory-service",
  "consumer": "search-service",
  "fields": {"product_id": "string", "count": "integer"}
}
